 * deferred now (OPEN, or VOID when voided while deferred, or SETTLED when settled while a statement bound it, with that date after the sheet's
 * today and no statement binding it — a bound claim's deferral waits for the binding to end: it counts in no total, is not overdue and cannot be
 * settled), and the number the claim it was split off shows (null unless it was split off one). */
export type Claim = {
  id: number;
  person: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: number | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  periodNumber: string | null;
  dueBy: string;
  log: ClaimLogLine[];
  deferredUntil: string | null;
  deferred: boolean;
  /** How many proofs the claim has: one above the sheet's proof threshold needs one to be settled or approved. */
  proofs: number;
  /** How many of its proofs are photos; the rest are receipts. */
  photos: number;
  splitFrom: string | null;
  /** The user whose open editor locks the claim against everyone else's edit button (null when none does). */
  lockedBy: string | null;
  /** Whether it was added while the period its due-by falls in was soft-closed. */
  lateEntry: boolean;
  /** The sheet's today it was last reminded on (null when never): an OPEN or PENDING claim is reminded once per day. */
  remindedOn: string | null;
  /** Its external reference, trimmed (null for none): no two claims on the sheet share one, ignoring case. */
  ref: string | null;
  /** Its tags: each trimmed and lower-cased, repeats dropped, sorted (a claim split off another carries its tags). */
  tags: string[];
  /** Every tag it has ever carried, sorted: the sheet lists a due-total for each tag any of its claims ever carried. */
  tagsEver: string[];
  /** The number of the bulk settle batch that last settled it (null when settled one at a time, or never). */
  batch: number | null;
  /** Its comments, in the order written. */
  comments: ClaimComment[];
  /** Its lines, in the order added: with any, its amount is their quantities times unit amounts added up. */
  lines: ClaimLine[];
  /** When it was added (the claim sequence's value; null when kept from before it was recorded): it sees only the
   *  forward-only rates saved before it (see {@link claimRateOf}). */
  added: number | null;
  /** Whether a steward waived its late charge (only while OPEN or PENDING, once): from then on it bears none. */
  waived: boolean;
  /** Whether it is held (toggled while OPEN or PENDING): while held, unless bound by a statement, it counts in no due figure (it stays in claimed). */
  held: boolean;
  /** The people it is shared with, in the order shared, each with their share of its due (a percent, two decimals):
   *  each holder's due figures count their part of it (see {@link partCents}), its own person's the rest. */
  shares: ClaimShare[];
  /** The user a steward assigned it to review while it was REVIEW (null when none; kept once reviewed). */
  reviewAssigned: string | null;
};

/** One share of a claim: the person holding it, and their share of its due (a percent with two decimals). */
export type ClaimShare = { person: number; share: string };

/** A holder's part of a claim's due (in hundredths): the due times their share divided by 100, rounded half to even. */
export function partCents(due: bigint, share: string): bigint {
  const product = due * hundredths(share);
  const negative = product < 0n;
  const abs = negative ? -product : product;
  let quotient = abs / 10000n;
  const remainder = abs % 10000n;
  if (remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n)) quotient += 1n;
  return negative ? -quotient : quotient;
}

/** What a claim's own person counts of its due (in hundredths): the due less the holders' parts. */
export function ownCents(claim: Claim, due: bigint): bigint {
  return (claim.shares ?? []).reduce((rest, s) => rest - partCents(due, s.share), due);
}

/** The person's parts of the claims shared with them (in hundredths), each with the claim: of the claims that count
 *  as their own persons count them (see {@link counted}); a claim with no due gives no part. */
export function heldParts(
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  person: Person,
  floor: DatedCents,
  late: Late,
): { claim: Claim; cents: bigint }[] {
  const byId = new Map(people.map((p) => [p.id, p]));
  const parts: { claim: Claim; cents: bigint }[] = [];
  for (const c of claims) {
    const share = (c.shares ?? []).find((s) => s.person === person.id);
    const owner = byId.get(c.person);
    if (share === undefined || owner === undefined || counted([c], [owner]).length === 0) continue;
    const due = claimDueCents(c, claimRateOf(rates, gradeOn(owner, c.date), c), floor, late);
    if (due !== undefined) parts.push({ claim: c, cents: partCents(due, share.share) });
  }
  return parts;
}

/** One line of a claim: its label, quantity (a whole number) and unit amount (two decimals). */
export type ClaimLine = { label: string; qty: number; unit: string };

/** One comment on a claim: the user who wrote it, the sheet's today then (yyyy-MM-dd), and its text. */
export type ClaimComment = { by: string; on: string; text: string };

/** One line of a claim's status log: the status it took, by whom, on the sheet's today then (yyyy-MM-dd), and the
 * claim's due as computed at that moment (two decimals, or n/a). */
export type ClaimLogLine = { status: ClaimStatus; by: string; on: string; due: string };

export const claimsKey = (sheet: string) => ['claims', sheet] as const;

export const claimsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/claims`;

/** Every claim on the sheet, newest first. */
export function useClaims(sheet: string) {
  const read = useReadScope(claimsKey(sheet));
  return useQuery({
    queryKey: read.key,
    queryFn: () => read.get<Claim[]>(claimsPath(sheet)),
  });
  return total;
}

/** A claim's due: the one fixed when settled; else the one its statement bound (as shown then); else its floored figure (the greater of the sheet's floor
 *  in force on its date and its figure) plus, while it is overdue, its late charge on that floored figure (a correction has no floor and no charge). */
export function claimDueCents(claim: Claim, pct: string | undefined, floor: DatedCents, late: Late): bigint | undefined {
  const figure = claimFigureCents(claim, pct, floor, roundsHalfUp(claim, late));
  if (figure === undefined || claim.settledDue !== null || bound(claim) || correction(claim)) return figure;
  const least = floor(claim.date);
  const floored = figure >= least ? figure : least;
  return floored + lateCents(claim, floored, late);
}


/** A person's due-total: the sum of their counted claims' rounded figures (the claims of others are skipped). n/a (undefined) when their grade
 *  has no rate on the sheet's today, unless a claim has a figure apart from it (settled, stated, at another grade
 *  in force on its date, or from a rate that ended by today on a claim not dated after it): then the figures there are.
 *  With a cap (the person's: the sheet's cap less their cut total), a due-total above it is the cap (an n/a one is not capped). */
export function personDueCents(
  claims: Claim[],
  rates: Rate[],
  person: Person,
  today: string | undefined,
  floor: DatedCents,
  late: Late,
  cap?: bigint,
  people: Person[] = [person],
): bigint | undefined {
  const sum = uncappedPersonDueCents(claims, rates, person, today, floor, late, people);
  return sum !== undefined && cap !== undefined && sum > cap ? cap : sum;
}

/** A person's due-total before the cap: the sum of their figures (see {@link personDueCents}). */
export function uncappedPersonDueCents(
  claims: Claim[],
  rates: Rate[],
  person: Person,
  today: string | undefined,
  floor: DatedCents,
  late: Late,
  people: Person[] = [person],
